import { fileURLToPath } from "node:url";
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

const host = process.env.TAURI_DEV_HOST;
// VITE_WEB=1 builds the browser version with the WebAssembly engine
// (src/wasm/, generated by `npm run build:wasm`); otherwise the desktop build
// gets a stub and talks to Tauri commands.
const web = !!process.env.VITE_WEB;
const here = (p: string) => fileURLToPath(new URL(p, import.meta.url));

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  base: process.env.VITE_BASE ?? "/",
  clearScreen: false,
  resolve: {
    alias: {
      "@gup-wasm": here(web ? "./src/wasm/gup_wasm.js" : "./src/wasmStub.ts"),
    },
  },
  server: {
    port: 1420,
    strictPort: true,
    host: host || false,
    watch: { ignored: ["**/src-tauri/**", "**/crates/**", "**/target/**"] },
  },
  build: {
    target: "es2021",
    minify: process.env.TAURI_DEBUG ? false : "esbuild",
    sourcemap: !!process.env.TAURI_DEBUG,
  },
  test: {
    environment: "node",
    include: ["src/**/*.test.ts"],
  },
});
